import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A person as the screen shows them, with their statement count and their last statement's
     *  due-total (two decimals; null when it was n/a or they have none) and date, and the date
     *  they are retired from (null while not retired), their past retirements, their snapshot lines (oldest first), their statement lines (by date, oldest first), whether they have any hold, their holds, and the ids of
     *  their patrons in the order they were named, and whether the signed-in user watches them. The grade is the one in force on the sheet's
     *  today; grades lists every grade they have been given, by from-date, the first one undated; terms
     *  are their own terms in days in force on the sheet's today (null when they have none then). Clashing: their name or an alias is
     *  also a name or alias on another sheet of the sheet's tree. */
    public record PersonView(long id, String name, String grade, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held, List<Person.Hold> holds,
            List<Long> patronIds, List<Person.DatedGrade> grades, boolean watched, Integer terms,
            String contact, List<String> aliases, boolean clashing, String origin,
            List<Person.Retirement> retirements, String tags, List<SnapshotLine> snapshots,
            List<StatementLine> statements, String flag) {
        public static PersonView of(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
                boolean watched, boolean clashing) {
            return of(p.getId(), p, today, s, patronIds, watched, clashing);
        }

        /** The person of the id, which a version rebuilt from the sheet's history does not carry. */
        static PersonView of(long id, Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
                boolean watched, boolean clashing) {
            return new PersonView(id, p.getName(), p.gradeOn(today), p.getVersion(), s.count(),
                    s.lastDueTotal() == null ? null : s.lastDueTotal().setScale(2).toPlainString(), s.lastDate(),
                    p.getRetiredFrom(), p.isHeld(), p.getHolds(), patronIds, p.getGrades(), watched, p.termsOn(today),
                    p.getContact(), p.getAliases(), clashing, p.getOriginSheetId(), p.getRetirements(),
                    p.getTags(), p.getSnapshots().stream().map(SnapshotLine::of).toList(),
                    s.lines().stream().map(StatementLine::of).toList(), p.flagOn(today));
        }
    }

    /** A statement line as the screen shows it: the date the statement shows and its due-total
     *  (two decimals; null when it was n/a). */
    public record StatementLine(LocalDate date, String dueTotal) {
        static StatementLine of(StatementSummary.Line l) {
            return new StatementLine(l.date(), l.dueTotal() == null ? null : l.dueTotal().setScale(2).toPlainString());
        }
    }

    /** A snapshot line as the screen shows it: the day being left and the person's due-total on it
     *  (two decimals; null when it was n/a). */
    public record SnapshotLine(LocalDate day, String dueTotal) {
        static SnapshotLine of(Person.Snapshot s) {
            return new SnapshotLine(s.day(), s.dueTotal() == null ? null : s.dueTotal().setScale(2).toPlainString());
        }
    }

    /** A person's values as the form submits them; the name is stored with surrounding spaces removed.
     *  An edit carries the version of the person its editor loaded, and the date its grade is in
     *  force from (null: the sheet's today); an add's grade is in force from the beginning of time.
     *  The terms are the person's own in whole days, blank or null for none; an edit records them
     *  from termsFrom (null: from the beginning of time). The contact is stored
     *  trimmed and lower-cased; blank or null for none. The tags are comma separated, taken as a
     *  claim's are; blank or null for none. */
    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            Long version,
            LocalDate gradeFrom,
            @Pattern(regexp = "\\s*\\d{0,4}\\s*") String terms,
            LocalDate termsFrom,
            @Size(max = 200) String contact,
            @Size(max = 1000) String tags) {

        /** The terms in days; null when blank. */
        public Integer termsDays() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }

        /** The tags as stored: lower-case, sorted and comma separated, without repeats; null when none. */
        public String tagsValue() {
            return ClaimService.tagsOf(tags);
        }

        /** The contact as stored: trimmed and lower-cased; null when blank. */
        public String contactValue() {
            return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
        }
    }

    /** An alias as the row submits it; stored trimmed. */
    public record AliasForm(@Size(max = 200) String alias) {
    }

    /** A retirement as the row submits it; a missing date takes the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** A hold as the row submits it: a missing from-date takes the sheet's today; a missing to-date
     *  leaves it open-ended. */
    public record HoldForm(LocalDate from, LocalDate to) {
    }
            @RequestBody(required = false) HoldForm body) {
        return view(sheetId, user, service.hold(sheetId, user.trim(), id, body == null ? null : body.from(),
                body == null ? null : body.to()));
    }

    @PostMapping("/{id}/flag")
    public PersonView flag(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody FlagForm body) {
        return view(sheetId, user, service.flag(sheetId, user.trim(), id, body.reason(), body.until()));
    }

    @PostMapping("/{id}/aliases")
    public PersonView addAlias(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody AliasForm body) {
        return view(sheetId, user, service.addAlias(sheetId, user.trim(), id, body.alias()));
    }

    @PostMapping("/{id}/patrons")
    public PersonView addPatron(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PatronForm body) {
        return view(sheetId, user, service.addPatron(sheetId, user.trim(), id, body.patronId()));
    }
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return person;
    }

    /** Give the person an alias (trimmed); refused when blank, or when it equals, ignoring case, any
     *  name or alias on the sheet. */
    @Transactional
    public Person addAlias(String sheetId, String user, long id, String alias) {
        if (sheets.archived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived: nothing on it may change");
        }
        Person person = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        String trimmed = alias == null ? "" : alias.trim();
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "An alias may not be blank");
        }
        requireUnusedName(sheetId, null, trimmed);
        person.addAlias(trimmed);
        try {
            people.flush();
        } catch (DataIntegrityViolationException e) {
            throw nameInUse(); // given by another user at the same moment
        } catch (ObjectOptimisticLockingFailureException e) {
            throw savedByAnother(); // saved by another user at the same moment
        }
        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " alias=" + trimmed);
        return person;
    }

    /** Add a person to the sheet (the sheet is created first if it was never loaded); {@code contact}
     *  (trimmed and lower-cased, null: none) is refused when another person on the sheet has it;
     *  {@code tags} (as {@link net.officefloor.hq.app.claim.ClaimService#tagsOf} has them, null: none). */
     *  sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The terms recorded since, by the date each is in force from ({@link #NO_TERMS}: none). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "terms", nullable = false)
    private Map<LocalDate, Integer> datedTerms = new HashMap<>();

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags: lower-case, sorted and comma separated, without repeats; null when they
     *  have none. A claim counts for a tag its person carries as well as for its own. */
    @Column(name = "tags")
    private String tags;

    /** The person's aliases, kept trimmed: other names the person is found by. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** The date the person is retired from; null while not retired. Set, they count as retired
     *  at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's past retirements, in the order they were unretired: no claim dated after the
     *  from-date and before the to-date of one can be added for them. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "position")
    private List<Retirement> retirements = new ArrayList<>();

    /** The person's holds, in the order they were added: their OPEN claims dated within one count
     *  in no live total (unless bound by a statement). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "position")
    private List<Hold> holds = new ArrayList<>();

    /** The person's snapshot lines, oldest first: one written each time the sheet's today moves.
     *  Taking one is no edit of the person, so it leaves their version as it is. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_snapshot", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "position")
    @OptimisticLock(excluded = true)
    private List<Snapshot> snapshots = new ArrayList<>();

    /** The person's place in the sheet's list: people are listed by it, lowest first. Moving a
     *  person is no edit of them, so it leaves their version as it is. */
    @Column(name = "list_position", nullable = false)
    @OptimisticLock(excluded = true)
    private long position;

    /** The id of the sheet the person was transferred from; null for anyone not transferred here. */
    @Column(name = "origin_sheet_id")
    private String originSheetId;

    /** The sheet's today on which a transfer brought the person here; null for anyone not
     *  transferred here. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The reason a steward flagged the person; null when never flagged. */
    @Column(name = "flag_reason")
    private String flagReason;

